78	DefaultPieceStorage::DefaultPieceStorage(
79	    const std::shared_ptr<DownloadContext>& downloadContext,
80	    const Option* option)
81	    : downloadContext_(downloadContext),
82	      bitfieldMan_(make_unique<BitfieldMan>(downloadContext->getPieceLength(),
83	                                            downloadContext->getTotalLength())),
84	      diskWriterFactory_(std::make_shared<DefaultDiskWriterFactory>()),
85	      endGame_(false),
86	      endGamePieceNum_(END_GAME_PIECE_NUM),
87	      option_(option),
88	      // The DefaultBtInteractive has the default value of
89	      // lastHaveIndex of 0, so we need to make nextHaveIndex_ more
90	      // than that.
91	      nextHaveIndex_(1),
92	      pieceStatMan_(std::make_shared<PieceStatMan>(
93	          downloadContext->getNumPieces(), true)),
94	      pieceSelector_(make_unique<RarestPieceSelector>(pieceStatMan_)),
95	      wrDiskCache_(nullptr)
96	{
97	  const std::string& pieceSelectorOpt =
98	      option_->get(PREF_STREAM_PIECE_SELECTOR);
99	  if (pieceSelectorOpt.empty() || pieceSelectorOpt == A2_V_DEFAULT) {
100	    streamPieceSelector_ =
101	        make_unique<DefaultStreamPieceSelector>(bitfieldMan_.get());
102	  }
103	  else if (pieceSelectorOpt == V_INORDER) {
104	    streamPieceSelector_ =
105	        make_unique<InorderStreamPieceSelector>(bitfieldMan_.get());
106	  }
107	  else if (pieceSelectorOpt == A2_V_RANDOM) {
108	    streamPieceSelector_ =
109	        make_unique<RandomStreamPieceSelector>(bitfieldMan_.get());
110	  }
111	  else if (pieceSelectorOpt == A2_V_GEOM) {
112	    streamPieceSelector_ =
113	        make_unique<GeomStreamPieceSelector>(bitfieldMan_.get(), 1.5);
114	  }
115	}
