145	/**
146	 * Newly instantiated piece is not added to usedPieces.
147	 * Because it is waste of memory and there is no chance to use them later.
148	 */
149	std::shared_ptr<Piece> DefaultPieceStorage::getPiece(size_t index)
150	{
151	  std::shared_ptr<Piece> piece;
152	  if (index <= bitfieldMan_->getMaxIndex()) {
153	    piece = findUsedPiece(index);
154	    if (!piece) {
155	      piece =
156	          std::make_shared<Piece>(index, bitfieldMan_->getBlockLength(index));
157	      if (hasPiece(index)) {
158	        piece->setAllBlock();
159	      }
160	    }
161	  }
162	  return piece;
163	}
