172	std::shared_ptr<Piece> DefaultPieceStorage::findUsedPiece(size_t index) const
173	{
174	  auto p = std::make_shared<Piece>();
175	  p->setIndex(index);
176	
177	  auto i = usedPieces_.find(p);
178	  if (i == usedPieces_.end()) {
179	    p.reset();
180	    return p;
181	  }
182	  else {
183	    return *i;
184	  }
185	}
