261	void DefaultPieceStorage::createFastIndexBitfield(
262	    BitfieldMan& bitfield, const std::shared_ptr<Peer>& peer)
263	{
264	  const auto& is = peer->getPeerAllowedIndexSet();
265	  for (const auto& i : is) {
266	    if (!bitfieldMan_->isBitSet(i) && peer->hasPiece(i)) {
267	      bitfield.setBit(i);
268	    }
269	  }
