280	void DefaultPieceStorage::getMissingPiece(
281	    std::vector<std::shared_ptr<Piece>>& pieces, size_t minMissingBlocks,
282	    const std::shared_ptr<Peer>& peer,
283	    const std::vector<size_t>& excludedIndexes, cuid_t cuid)
284	{
