486	    if (downloadContext_->hasAttribute(CTX_ATTR_BT)) {
487	      if (!bittorrent::getTorrentAttrs(downloadContext_)->metadata.empty()) {
488	#  ifdef __MINGW32__
489	        // On Windows, if aria2 opens files with GENERIC_WRITE access
490	        // right, some programs cannot open them aria2 is seeding. To
491	        // avoid this situation, re-open the files with read-only
492	        // enabled.
493	        A2_LOG_INFO("Closing files and re-open them with read-only mode"
494	                    " enabled.");
495	        diskAdaptor_->closeFile();
496	        diskAdaptor_->enableReadOnly();
497	        diskAdaptor_->openFile();
498	#  endif // __MINGW32__
499	        auto group = downloadContext_->getOwnerRequestGroup();
500	
501	        util::executeHookByOptName(group, option_,
502	                                   PREF_ON_BT_DOWNLOAD_COMPLETE);
503	        SingletonHolder<Notifier>::instance()->notifyDownloadEvent(
504	            EVENT_ON_BT_DOWNLOAD_COMPLETE, group);
505	
506	        group->enableSeedOnly();
507	      }
508	    }
509	#endif // ENABLE_BITTORRENT
510	  }
