342	  A2_LOG_DEBUG(fmt("updateWrCache entry=%p", wrCache_.get()));
343	  auto cell = new WrDiskCacheEntry::DataCell();
344	  cell->goff = goff;
345	  cell->data = data;
346	  cell->offset = offset;
