356	size_t Piece::appendWrCache(WrDiskCache* diskCache, int64_t goff,
357	                            const unsigned char* data, size_t len)
358	{
359	  if (!diskCache) {
360	    return 0;
361	  }
362	  assert(wrCache_);
363	  size_t delta = wrCache_->append(goff, data, len);
364	  bool rv;
365	  if (delta > 0) {
366	    rv = diskCache->update(wrCache_.get(), delta);
367	    assert(rv);
368	  }
369	  return delta;
370	}
