154	bool BitfieldMan::hasMissingPiece(const unsigned char* peerBitfield,
155	                                  size_t length) const
156	{
157	  if (bitfieldLength_ != length) {
158	    return false;
159	  }
160	  bool retval = false;
161	  for (size_t i = 0; i < bitfieldLength_; ++i) {
162	    unsigned char temp = peerBitfield[i] & ~bitfield_[i];
163	    if (filterEnabled_) {
164	      temp &= filterBitfield_[i];
165	    }
166	    if (temp & 0xffu) {
167	      retval = true;
168	      break;
169	    }
170	  }
171	  return retval;
172	}
