231	namespace {
232	template <typename Array>
233	size_t getEndIndex(size_t index, const Array& bitfield, size_t blocks)
234	{
235	  while (index < blocks && !bitfield::test(bitfield, blocks, index)) {
236	    ++index;
237	  }
238	  return index;
239	}
