467	bool copyBitfield(unsigned char* dst, const Array& src, size_t blocks)
468	{
469	  unsigned char bits = 0;
470	  size_t len = (blocks + 7) / 8;
471	  for (size_t i = 0; i < len - 1; ++i) {
472	    dst[i] = src[i];
473	    bits |= dst[i];
474	  }
475	  dst[len - 1] = src[len - 1] & bitfield::lastByteMask(blocks);
476	  bits |= dst[len - 1];
477	  return bits != 0;
478	}
479	} // namespace
