902	int64_t BitfieldMan::getOffsetCompletedLength(int64_t offset,
903	                                              int64_t length) const
904	{
905	  int64_t res = 0;
906	  if (length == 0 || totalLength_ <= offset) {
907	    return 0;
908	  }
909	  if (totalLength_ < offset + length) {
910	    length = totalLength_ - offset;
911	  }
912	  size_t start = offset / blockLength_;
913	  size_t end = (offset + length - 1) / blockLength_;
914	  if (start == end) {
915	    if (isBitSet(start)) {
916	      res = length;
917	    }
918	  }
919	  else {
920	    if (isBitSet(start)) {
921	      res += static_cast<int64_t>(start + 1) * blockLength_ - offset;
922	    }
923	    for (size_t i = start + 1; i <= end - 1; ++i) {
924	      if (isBitSet(i)) {
925	        res += blockLength_;
926	      }
927	    }
928	    if (isBitSet(end)) {
929	      res += offset + length - static_cast<int64_t>(end) * blockLength_;
930	    }
931	  }
932	  return res;
933	}
